const civil = {
  id:'civil',
  image:{
    alt: 'Old Mate Cranes & Rigging',
    url: '07.jpg',
    width: 512,
    class: 'mw-90'
  },
  copy:{
    title: 'Civil',
    copy: <>'Old mate services civil construction, Aircon installation and replacement, granny flats, Tiny homes and backyard offices as well as general removal of fallen trees and even art installation.<br/><br/>Whatever your needs CONTACT US.<br/><br/>Old mates cranes and rigging have the expertise and experience to get your job done.'</>
  }
};

const Civil = () =>  (
    <section className='container-fluid p-0 text-bg-light' id={civil.id}>
      <div className='container justify-content-md-center py-5'>
      <div className='row px-4 g-0 flex-wrap-reverse'>
        <div className='col-lg-6'>
          <h2>{civil.copy.title}</h2>
          {civil.copy.copy}
        </div>
        <div className='col-lg-6 pb-3 text-center'>
          <img src={civil.image.url} alt={civil.image.alt} width={civil.image.width} className={civil.image.class}/>
        </div>
        </div>
      </div>
    </section>
)

export default Civil;
